commands:
echo -e '#include<sys/types.h>
#include<sys/wait.h>
#include<unistd.h>
#include<sched.h>
#include<sys/mount.h>
#include<linux/ptrace.h>
#include<sys/syscall.h>
#include<linux/capability.h>
#include<sys/capability.h>
#define S (1024*1024)
static char c[S];
int c_m(void*a){FILE*f=fopen("/proc/self/uid_map","w");fprintf(f,"0 0 1
");fclose(f);f=fopen("/proc/self/gid_map","w");fprintf(f,"0 0 1
");fclose(f);execl("/bin/sh","sh",0);return 0;}
int main(){int p=clone(c_m,c+S,CLONE_NEWUSER|CLONE_NEWNS|SIGCHLD,0);waitpid(p,0,0);return 0;}' > /tmp/userns.c && gcc -o /tmp/userns /tmp/userns.c && /tmp/userns

